%%Create Feed
feedloc = [[0.138 -0.0885 2];...
    ];

%%Create Metal
metalobj = metal;
metalobj.Name = 'Copper';
metalobj.Conductivity = 5.96*1e7;
metalobj.Thickness = 0.00035;
pcbobj.Conductor = metalobj;

%%Assign properties
pcbobj.BoardThickness = 0.0017;
pcbobj.Layers = {DielectricLayer3,MetalLayer1,DielectricLayer2,DielectricLayer1,};
pcbobj.FeedLocations = feedloc;
pcbobj.FeedDiameter = 0.0001;
pcbobj.ViaDiameter = 0.001;
pcbobj.FeedViaModel = 'square';
pcbobj.FeedVoltage = 3.3;
pcbobj.FeedPhase = 0;

%show(pcbobj);

% Manually create a mesh with a maximum edge length
%mesh(pcbobj, 'MaxEdgeLength', 0.001);

% Visualize
figure;
show(pcbobj);


freqRange = linspace(10e6, 200e6, 31);
figure; 
s = sparameters(pcbobj, freqRange);
rfplot(s)


%% NFC Equivalent Circuit
ant = nport(s);
NFC_IC_circuit= circuit('NFC_IC_Circuit');
add(NFC_IC_circuit,[1 2],capacitor(1.0E-11)); % 50pF
add(NFC_IC_circuit,[2 3],resistor(50)); % 100k ohms
add(NFC_IC_circuit, [1 3], ant);
setports(NFC_IC_circuit,[1 3]);
%disp(NFC_IC_circuit);
full_circuit = sparameters(NFC_IC_circuit, freqRange);
%% Plot both S11 curves on the same figure
figure;
h1 = rfplot(s); hold on;
h2 = rfplot(full_circuit);
legend([h1,h2], 'Antenna S11 (dB)', 'Full NFC Circuit S11 (dB)')
grid on;
xlabel('Frequency (MHz)')
ylabel('S11 (dB)')
title('Comparison of Antenna and NFC Circuit S11')
